package com.farm2market.controller;
import com.farm2market.entity.*; import com.farm2market.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController {final UserRepository users;final ProductRepository products;final OrderRepository orders;AdminController(UserRepository u,ProductRepository p,OrderRepository o){users=u;products=p;orders=o;} @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("success",true,"data",Map.of("farmers",users.countByRole(Role.FARMER),"buyers",users.countByRole(Role.BUYER),"products",products.count(),"activeListings",products.countByActiveTrue(),"orders",orders.count()));} @GetMapping("/users") public List<User> user(){return users.findAll();} @GetMapping("/products") public List<Product> product(){return products.findAll();} @GetMapping("/orders") public List<Order> order(){return orders.findAll();} @GetMapping("/turnover") public Map<String,Object> turnover(){return Map.of("success",true,"data",orders.findAll().stream().mapToDouble(o->o.getTotalAmount()==null?0:o.getTotalAmount()).sum());}}
